package main

import (
	"fmt"
	"runtime/pprof"
	"sync"
	"time"
)

var mu sync.Mutex

func main() {
	var wg sync.WaitGroup
	mu.Lock()
	for range 3 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			mu.Unlock()
		}()
	}
	time.Sleep(20 * time.Millisecond)
	mu.Unlock()
	wg.Wait()
	fmt.Println("block records:", pprof.Lookup("block").Count())
}

package main

import (
	"log"
	"net/http"
	"net/http/pprof"
	"runtime"
)

func serveDebug(addr string) {
	mux := http.NewServeMux()
	mux.HandleFunc("/debug/pprof/", pprof.Index)
	log.Println(http.ListenAndServe(addr, mux))
}

func main() {
	runtime.SetBlockProfileRate(1)
	runtime.SetMutexProfileFraction(1)
	go serveDebug(":6060")
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", http.NotFoundHandler()))
}
